from pathlib import Path

p = Path('Frontend/src/pages/testing.js')
s = p.read_text(encoding='utf-8')
s = s.replace('let d = state.draft;', 'let d = state.draft;\n  const live = (d.method || "live") === "live";')
s = s.replace('Evaluate a real screenshot through one of your personas.', 'Let your persona use a live website and share its experience.')
s = s.replace('<small>The URL records context. The selected screenshot is what Gemini evaluates.</small>', '<small>The persona opens this URL in Chrome and interacts with the page.</small><label for="method">Testing method</label><select id="method" name="method"><option value="live" ${live ? "selected" : ""}>Live persona session</option><option value="screenshot" ${!live ? "selected" : ""}>Screenshot review</option></select>')
s = s.replace('Screenshot evaluation', 'Live browser interaction')
start = s.index('<label for="screenshot">')
end = s.index('<label for="project">', start)
s = s[:start] + '${live ? `<label for="max-actions">Maximum interactions</label><input id="max-actions" name="max_actions" type="number" min="1" max="60" value="${esc(d.max_actions || 20)}"><small>The persona clicks, scrolls, and fills safe fields. Account submissions and payments remain outside this session.</small>` : `' + s[start:end] + '`}' + s[end:]
s = s.replace('The screenshot is sent to Gemini only when you start the evaluation.', 'The persona uses the live page when you start the session. Feedback is based on its recorded actions.')
s = s.replace('${d.screenshot_id ?', '${!live && d.screenshot_id ?')
s = s.replace('Review criteria for this screenshot. This is not a browser action script.', 'Review the persona criteria and task before starting the session.')
s = s.replace('<img class="screen-preview" src="${imageUrl(p.screenshot_id)}" alt="Screenshot to be analyzed">', '${p.method === "live" ? "" : `<img class="screen-preview" src="${imageUrl(p.screenshot_id)}" alt="Screenshot to be analyzed">`}')
s = s.replace('All selected cases are supplied to one screenshot evaluation. No clicks, submissions, task completion or per-case passes are inferred.', '${p.method === "live" ? "The persona chooses actions on the live website, then shares first-person feedback tied to recorded steps. This is a simulated persona experience." : "Selected cases guide the screenshot review."}')
s = s.replace('${done ? "Report ready" : failed ? "Evaluation failed" : "Screenshot analysis"}', '${done ? "Report ready" : failed ? "Evaluation needs attention" : p.method === "live" ? "Live persona session" : "Screenshot analysis"}')
s = s.replace('<img class="screen-preview evidence-full" src="${imageUrl(p.screenshot_id)}" alt="Actual screenshot submitted for evaluation">', '${p.method === "live" ? `<div class="hint spacer">Chrome is running the persona task. Follow its recorded actions in the activity log below.</div>` : `<img class="screen-preview evidence-full" src="${imageUrl(p.screenshot_id)}" alt="Actual screenshot submitted for evaluation">`}')
s = s.replace('["queued", "preparing", "analyzing", "completed"]', '(p.method === "live" ? ["queued", "preparing", "exploring", "reviewing", "completed"] : ["queued", "preparing", "analyzing", "completed"])')
s = s.replace('${done ? link(', '${r.report_id ? link(')
s = s.replace('Screenshot analysis cannot be paused or stopped once sent to Gemini.', 'Sessions run up to the configured interaction limit and cannot currently be paused.')
p.write_text(s, encoding='utf-8')
p = Path('Frontend/src/app.js')
s = p.read_text(encoding='utf-8').replace('event.target.id === "screenshot" || event.target.id === "persona"', 'event.target.id === "method" || event.target.id === "screenshot" || event.target.id === "persona"')
p.write_text(s, encoding='utf-8')
p = Path('Backend/app/server.py')
s = p.read_text(encoding='utf-8').replace("'browser_journeys':False", "'browser_journeys':True")
s = s.replace("Inspect visible evidence relevant to", "Inspect recorded evidence relevant to")
p.write_text(s, encoding='utf-8')
p = Path('Frontend/src/pages/reports.js')
s = p.read_text(encoding='utf-8').replace('${findings(r)}${feedback(r)}', '${feedback(r)}${findings(r)}')
p.write_text(s, encoding='utf-8')
